  ('arequipa-colca-canyon-peru', '10S', 'Arequipa & the Colca Canyon, Peru', 'Peru', 'White stone, three volcanoes, one canyon', 'live', 'verified', 'mountainValley', 'Lima, South Coast & Amazon', '{"expedition","romance","culture"}', '{}', '{"essential","comfort","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"105","tourist_assistance":"iPerú","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"air_access":"Rodríguez Ballón International (AQP) via Lima (LIM)","altitude_m":{"arequipa":2335,"chivay":3650,"canyon_rim":3800,"patapampa_pass":4910,"misti_summit":5822,"chachani_summit":6057},"water":"bottled/filtered","volcano_note":"El Misti active, monitored — no routine risk to city visitors","medevac":"Arequipa clinics stabilize; serious cases evac to Lima","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Within 20km south of the Peru-Colombia border FCDO advises against all but essential travel to areas within 20km south of the Putumayo River and the border between Peru and Colombia (Loreto region) except for: the Amazon River the area of the triple border with Brazil and Colombia from and including the towns of Caballococha in Peru up to the actual triple border at Santa Rosa de Yavari town Valley of the Apurímac, Ene, and Mantaro Rivers ( VRAEM ) FCDO advises against all but essential travel to the Valley of the Apurímac, Ene, and Mantaro Rivers, also known as the VRAEM region."},{"form":"against all but essential travel","text":"advise against all but essential travel to these two areas for safety and security reasons."},{"form":"against all but essential travel","text":"advises against all but essential travel to areas within 20km south of the Putumayo River and the border between Peru and Colombia (Loreto region) except for: the Amazon River the area of the triple border with Brazil and Colombia from and including the towns of Caballococha in Peru up to the actual triple border at Santa Rosa de Yavari town This is due to a high level of violence from organised criminal gangs who produce and traffic illegal drugs."},{"form":"against all but essential travel","text":"advises against all but essential travel to the Valley of the Apurímac, Ene and Mantaro Rivers, also known as the VRAEM region."},{"form":"against all but essential travel","text":"advises against all but essential travel."}],"url":"https://www.gov.uk/foreign-travel-advice/peru","read":"2026-08-19","page_updated":"2026-06-22T23:35:12+01:00"}},"timing":{"peak":"April–November (dry season); condors best 9–11 a.m. year-round","green":"December–March (wet season)","inflection":"late March–early April (dry-season open); mid-to-late August (Arequipa founding anniversary)","fire_date":"mid-to-late March (adventure push) and late July / early August (anniversary push)","booking_lead":"3–6 months for peak / honeymoon at small-inventory ultra properties"},"jewels":[{"name":"Cruz del Cóndor","si_tag":"expedition","tier":"comfort","source":"https://turismoliberty.pe/en/arequipa-5-day-itinerary-2026/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Early-morning, high-altitude roadside viewpoint, cold, crowded rail edges Typically guided day/2-day tour; low physical risk but altitude + early start","si":"expedition","blurb":"Early-morning, high-altitude roadside viewpoint, cold, crowded rail edges Typically guided day/2-day tour; low physical risk but altitude + early start","when":"April–November","commission":"guided 1-/2-day Colca tour (net-rate)"},{"name":"Colca Canyon multi-day trek","si_tag":"expedition","tier":"comfort","source":"https://www.onmycanvas.com/hike-colca-canyon-arequipa-peru/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"~1,200 m descent then ~1,200 m ascent; steep switchbacks, heat on the climb-out, AMS exposure the whole way Guided recommended","si":"expedition","blurb":"~1,200 m descent then ~1,200 m ascent; steep switchbacks, heat on the climb-out, AMS exposure the whole way Guided recommended","when":"April–November","commission":"guided trek (net-rate, AOR-eligible)"},{"name":"Patapampa pass & vicuña flats","si_tag":"expedition","tier":"comfort","source":"https://turismoliberty.pe/en/arequipa-5-day-itinerary-2026/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"April–November","commission":"included in Colca tour"},{"name":"Misti & Chachani summits","si_tag":"expedition","tier":"comfort","source":"https://www.colcatours.com/mismi.htm","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"High-altitude mountaineering; Chachani is one of the \"easier\" 6,000 m peaks but still a serious ascent; cold, AMS, exertion Guided only","si":"expedition","blurb":"High-altitude mountaineering; Chachani is one of the \"easier\" 6,000 m peaks but still a serious ascent; cold, AMS, exertion Guided only","when":"April–November","commission":"certified mountaineering operator (net-rate)"},{"name":"Río Chili rafting","si_tag":"expedition","tier":"comfort","source":"https://www.ericadventures.com/en/arequipa/chili-rafting-tour-arequipa/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Class II–IV rapids between Misti and Chachani; cold water, altitude Guided/outfitter only. Confirm water-safety gear before booking","si":"expedition","blurb":"Class II–IV rapids between Misti and Chachani; cold water, altitude Guided/outfitter only. Confirm water-safety gear before booking","when":"April–November","commission":"rafting outfitter (net-rate)"},{"name":"Chivay & La Calera hot springs","si_tag":"expedition","tier":"comfort","source":"https://www.peruforless.com/blog/colca-canyon","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"April–November","commission":"included in tour; entry non-commissionable"},{"name":"Santa Catalina Monastery","si_tag":"C&H","tier":"comfort","source":"https://www.theonlyperuguide.com/research/things-to-do-in-arequipa-colonial-city-colca-canyon-local-culture/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"The monastery covers ~215,000 sq ft of streets, cloisters, and gardens — plan two to three hours","si":"culture","blurb":"The monastery covers ~215,000 sq ft of streets, cloisters, and gardens — plan two to three hours","when":"year-round","commission":"guided city tour; entry non-commissionable"},{"name":"Juanita the Ice Maiden (Andean Sanctuaries Museum)","si_tag":"C&H","tier":"essential","source":"https://www.peruforless.com/blog/inca-ice-maiden","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"included in city tour; entry non-commissionable"},{"name":"Yanahuara mirador","si_tag":"C&H","tier":"essential","source":"https://www.exoticca.com/us/blog/things-to-do-in-arequipa-must-see-hidden-gems/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"included in city tour"},{"name":"Sabandía Mill","si_tag":"C&H","tier":"essential","source":"https://www.exoticca.com/us/blog/things-to-do-in-arequipa-must-see-hidden-gems/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"April–November","commission":"countryside/city tour add-on"},{"name":"Toro Muerto petroglyphs","si_tag":"C&H","tier":"comfort","source":"https://www.exoticca.com/us/blog/things-to-do-in-arequipa-must-see-hidden-gems/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"April–November","commission":"full-day guided excursion (net-rate)"},{"name":"Picantería crawl (La Nueva Palomino)","si_tag":"C&H","tier":"comfort","source":"https://larepublica.pe/datos-lr/respuestas/2022/12/05/la-historia-de-la-nueva-palomino-la-picanteria-mas-famosa-de-arequipa-como-empezo-este-legado-familiar-gastronomia-peruana-evat","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"April–November","commission":"culinary tour / dining add-on"}],"faq":null,"seo":{"meta_title":"Arequipa & Colca Canyon, Peru: Condors, White-Stone City & High-Altitude Adventure | TravelWell","jsonld_type":"TouristDestination","search_language":"es-PE","local_keywords":["qué hacer en Arequipa","Cañón del Colca cóndores","Monasterio Santa Catalina","Cruz del Cóndor mejor hora","mejor época Colca Canyon","picanterías Arequipa rocoto relleno","escalar el Misti"],"hreflang":["en","es-PE"],"author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07"},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Las Casitas, A Belmond Hotel","location":"Colca Canyon","earning":"Virtuoso preferred + consortia","mor":"Virtuoso / Belmond direct via advisor","tier":"ultra"},{"name":"Cirqa — Relais & Châteaux","location":"Arequipa","earning":"R&C consortia (verify Virtuoso)","mor":"Relais & Châteaux / advisor","tier":"ultra"},{"name":"Casa Andina Premium Arequipa","location":"Arequipa","earning":"chain program / consortia (verify)","mor":"advisor / chain direct","tier":"premium"},{"name":"Katari at Plaza de Armas","location":"Arequipa","earning":"consortia / net-rate (verify)","mor":"advisor / direct","tier":"premium"}],"source_verified":null,"hero":{"query":"Arequipa & the Colca Canyon, Peru, Peru"},"geo":{"lat":-16.409,"lng":-71.5375}}'::jsonb, 33),
  ('bacalar-mexico', '10S', 'Bacalar', 'Mexico', '*If it''s the water so still and so many', 'live', 'verified', 'tropicalBeach', 'Quintana Roo (Cancún & Riviera Maya)', '{"tropical","wellness","adventure"}', '{"tropical"}', '{"essential","comfort","luxury"}', null, 'anchor', '{"key_facts":["Lagoon of Seven Colors - karst-fed (no river inputs), colors from depth/sand/cenotes/light","Active living-stromatolite colony (cyanobacteria, ~3.5B-yr lineage); <12 such colonies worldwide","Cenote Azul - one of Mexico''s largest open-air cenotes, ~70m across x up to ~90m deep","Eco-luxury cluster: Habitas Bacalar + Boca de Agua (future Wellness SI anchor)","Freshwater destination (no dive-cert node); ~3.5-4h south of Cancun - a stay-2-nights slow trip"],"safety":{"emergency":"911","advisory_level":"L2","nearest_trauma":"Chetumal (Hospital General, ~40 min south) or evac to Cancun","malaria":"NONE in tourist zone; dengue present","water":"bottled/purified","hurricane":"Jun-Nov, peak Aug-Oct","special_rule":"STROMATOLITE PROTECTION - no touch, no regular sunscreen (biodegradable only/none); a single handprint damages years of growth","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dry season Nov-Apr (calm-water AM); Dec-Apr hardest to book, Jan/Mar busiest","shoulder":"Nov and Feb-Mar (best value in dry window; avoid Semana Santa)","green":"Rainy Jun-Sep (afternoon showers, hurricane overlap) - fill-the-beds","booking_window_lead_time":"Longer than regional avg for dock-front/lagoon-front; best waterfront stock clears first for Dec-Apr","fill_the_beds":"Jun-Sep green + Nov/early-Dec shoulder; sell slow-travel/wellness (yoga, dawn paddle)","holiday_event_peaks":"Semana Santa (domestic crush), Dec holiday + New Year","campaign_start_trigger":"Live ~4-6 months ahead of Nov-Apr (by ~Jun-Jul); secondary green-season value push for Jun-Sep","source":"https://hellobacalar.com/guides/best-time-visit-bacalar"},"jewels":[{"name":"Los Rapidos + Canal de los Piratas sailboat circuit","si_tag":"tropical","status":"live","tier":"comfort","bookable_category":"lagoon tour","source":"https://www.thoroughlytravel.com/bacalar-lagoon/","hook":"half-day sail across the color bands past the pirate channel ·","si":"tropical","blurb":"half-day sail across the color bands past the pirate channel ·","commission":"affiliate ~4-8% (Viator/GYG) or lodge direct"},{"name":"Cenote Azul open-air swim","si_tag":"tropical","status":"live","tier":"essential","bookable_category":"cenote entry","source":"https://kendyltravels.com/bacalar-cenotes/","hook":"~70 m-wide, ~90 m-deep sky cenote with rim restaurant ·","si":"tropical","blurb":"~70 m-wide, ~90 m-deep sky cenote with rim restaurant ·","commission":"non-commissionable gate; bundle into day-tour"},{"name":"Cenote Negro (seventh color)","si_tag":"tropical","status":"live","tier":"comfort","bookable_category":"lagoon tour","source":"https://kendyltravels.com/bacalar-cenotes/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the deep-blue cenote said to complete the seven colors ·","si":"tropical","blurb":"the deep-blue cenote said to complete the seven colors ·","when":"Dry season Nov-Apr","commission":"affiliate via tour"},{"name":"Stromatolite kayak (Cenote Cocalitos)","si_tag":"globaladv","status":"future","tier":"comfort","bookable_category":"guided eco-tour","source":"https://sandinmycurls.com/bacalar-mexico-seven-color-lagoon-guide/","si":"adventure","commission":"guided-tour affiliate; no-touch/no-sunscreen mandatory"},{"name":"Eco-luxury lagoon lodge (Habitas / Boca de Agua)","si_tag":"wellness","status":"future","tier":"luxury","bookable_category":"boutique lodging","source":"https://www.bocadeagua.com/blog/best-hotels-bacalar-mexico","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"thatched cabins, yoga, clear kayaks, lagoon-front restaurant ·","si":"wellness","blurb":"thatched cabins, yoga, clear kayaks, lagoon-front restaurant ·","when":"Dry season Nov-Apr","commission":"on application, 10%+ boutique/luxury"},{"name":"Sunrise kayak + slow-water day","si_tag":"wellness","status":"future","tier":"comfort","bookable_category":"lodge activity","source":"https://www.bocadeagua.com/","si":"wellness","commission":"bundled in lodge rate"}],"faq":[{"q":"What''s the real risk to plan for in Bacalar?","a":"Open-water swimming discipline, mosquitoes and hurricanes - not crime. Cenote Azul is a sky-facing sinkhole up to ~90m deep with no floor, so treat it as open water (strong swimmers/life vests); use repellent for dengue (present, worse in the rainy season); hurricane season runs Jun-Nov, peaking Aug-Oct.","source":"kendyltravels.com","si_tag":"safety"},{"q":"Can you swim near the stromatolites - and is it allowed?","a":"Yes to swimming the lagoon, but the stromatolites are strictly no-touch and no-sunscreen. Do not touch, stand on, or apply regular sunscreen near the colonies - a single handprint can destroy years of microbial growth - so view and photograph from a kayak only, using biodegradable sunscreen or none. Bacalar is not a scuba destination, so there are no dive or no-fly considerations.","source":"sandinmycurls.com","si_tag":"globaladv"},{"q":"What is the Lagoon of Seven Colors, and how do you see it?","a":"It''s a karst-fed freshwater lagoon whose colors shift from turquoise to navy over its sand, cenotes and varying depths. The signature way to see it is a half-day catamaran or sailboat circuit past Los Rapidos, the stromatolites and the Canal de los Piratas; go on a calm morning when the water is glass-still.","source":"thoroughlytravel.com","si_tag":"tropical"},{"q":"Which are the best eco-luxury places to stay in Bacalar?","a":"Boca de Agua and Our Habitas Bacalar lead the lagoon. Boca de Agua is a Frida Escobedo-designed set of ~26 stilted treehouse villas on 82 acres with a MICHELIN Key 2025; Our Habitas is the established adults-only, wellness-led lagoon retreat ~20 min south of town. Both are direct/consortia bookings - book waterfront stock early for Dec-Apr.","source":"mrandmrssmith.com","si_tag":"wellness"},{"q":"When is the best time to visit Bacalar?","a":"November-April, the dry season, is best - warm, mostly dry, with glass-still calm-water mornings. Within that, November and Feb-March are the best value (avoid Semana Santa); the rainy green season, Jun-Sep, is lush, quiet and cheapest but brings afternoon showers and hurricane overlap.","source":"hellobacalar.com","si_tag":"tropical"}],"seo":{"meta_title":"Bacalar Mexico: Lagoon of Seven Colors & Stromatolites","meta_description":"Bacalar''s Lagoon of Seven Colors, living stromatolites and open-air cenotes - where to sail, swim and stay, and how to protect what you came to see.","slug":"bacalar-mexico","primary_keyword":"Bacalar Lagoon of Seven Colors","long_tail":["Bacalar stromatolites","Cenote Azul Bacalar","Bacalar eco lodges","Bacalar sailboat tour","Bacalar things to do"],"search_language":"bilingual (en + es-MX)","local_keywords":["Laguna de los Siete Colores","Bacalar que hacer","estromatolitos Bacalar","Cenote Azul Bacalar","hoteles Bacalar laguna","tour velero Bacalar","mejor epoca para visitar Bacalar"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister - commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":{"bin":"freely_bookable","level":"L2","codes":[],"consent_flow":false,"note":"Quintana Roo US L2 (Exercise Increased Caution, dated 2026-05-29) - freely bookable; the real planning is open-water swim discipline + stromatolite protection + hurricane season, not crime; MXN currency"},"si_checklist_25":{"run_date":"2026-07-31","hits":5,"misses":17,"disregarded":3,"note":"Canonical 25-SI list; FRESHWATER lagoon - Dive Globally is a MISS (no scuba/cenote-cert node here, unlike Cozumel/Chinchorro); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"tropical","name":"tropical","status":"live"},{"si":"wellness","name":"wellness","status":"future"},{"si":"globaladv","name":"adventure","status":"future"}],"ultra":[{"name":"Boca de Agua","price_tier":"ultra","what":"Frida Escobedo-designed eco-luxury, ~26 stilted treehouse villas on 82 acres, MICHELIN Key 2025","bookable":"direct + Mr & Mrs Smith (Hyatt) + MICHELIN Guide Hotels","earning":"on application / host-Virtuoso-or-Smith consortia","mor_posture":"broker to property/consortia; property-paid commission; no net-rate resale","direct_only_flag":false,"source":"https://www.mrandmrssmith.com/luxury-hotels/boca-de-agua"},{"name":"Our Habitas Bacalar","price_tier":"luxury-ultra","what":"Most established luxe-eco resort; adults-only, lagoon A-frame tents + jungle rooms, holistic wellness/spa","bookable":"direct + Mr & Mrs Smith + Ownia Collection","earning":"on application / host-consortia","mor_posture":"broker to property/consortia; property-paid commission","direct_only_flag":false,"source":"https://www.ourhabitas.com/bacalar/"}],"source_verified":"2026-07-04","hero":{"query":"Bacalar, Mexico"},"geo":{"lat":18.6767,"lng":-88.3953}}'::jsonb, 34),
  ('balandra-beach-mexico', '10S', 'Balandra Beach (Playa Balandra)', 'Mexico', 'Balandra beach La Paz', 'live', 'verified', 'tropicalBeach', 'Baja California Sur (Los Cabos & La Paz)', '{"tropical","family","romance"}', '{"tropical"}', '{"essential","comfort","premier"}', null, 'core', '{"key_facts":["CONANP Natural Protected Area since 2008; ~25 km north of La Paz","Two fixed daily shifts (08:00-12:00 / 13:00-17:00), ~450 visitors per slot, first-come","Conservation bracelet required ~MXN 125 pp/day (under-12s, seniors/retirees, disabilities exempt with ID)","No commercial food service inside the bay; limited services (toilets/info) - bring own water/shade/snacks","El Hongo mushroom rock is the emblem of Balandra and La Paz; shallow calm turquoise water"],"safety":{"emergency":"911","hospital":"limited on-site (toilets/info only); serious cases ~25 km to La Paz - Hospital Salvatierra/ISSSTE/private + air-evac; carry medical insurance","advisory_level":"L2","malaria":"effectively none in Baja California Sur","dengue":"circulates in Mexico - use repellent","water":"carry own bottled/purified water - no services in the bay","hurricane":"Jun-Nov - trip insurance for summer/fall","day_use":"TIMED-ENTRY two shifts + ~450/slot cap, first-come, arrive >=30 min early; CONANP bracelet required; NO food vendors inside","sun_heat":"scarce shade - umbrella, hat, reef-safe sunscreen, ample water","el_hongo":"protected/restored rock - do not climb or touch","swimming":"shallow, calm, family-safe but NO lifeguards - supervise children, watch outgoing tide; no diving (wading/kayak beach)","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Nov-Apr (dry desert winter, comfortable) - slot cap fills fastest, arrive early; rides La Paz high season","shoulder":"May & Sep-Oct (warm, quieter slots, easier entry)","green":"Jun-Aug (summer heat + hurricane window, scarce shade - early-slot only; domestic holidays spike)","booking_window_lead_time":"no lodging to pre-book; conservation bracelet is same-day/short-lead (CONANP digital or La Paz office); binding constraint is daily slot cap (~450/shift) - plan day, arrive early; book La Paz lodging on 3-6-month peak lead","out_of_season_fill_the_beds":"morning Balandra slot + Playa Tecolote (vendors allowed) + Malecon afternoon; sell as half-day postcard-beach anchor of a La Paz stay year-round","holiday_event_peaks":"Christmas-New Year, Semana Santa (Easter), Mexican summer holidays - domestic surges hit slot cap hardest","campaign_start_trigger":"add-on jewel, not standalone - market inside La Paz/Baja campaigns (Nov-Apr beach campaigns late summer; summer value in spring), always paired with La Paz lodging + transfer","flag":"no wildlife season; peak = weather + La Paz volume + Mexican holidays; NO lodging on-beach; hard visitor cap","sources":["https://www.thoroughlytravel.com/balandra-beach-mexico/","https://beachythings.site/playa-balandra-entrance-fee-rules/","https://mrplayas.com/la-paz/beaches"]},"jewels":[{"name":"El Hongo mushroom-rock walk + swim","si_tag":"tropical","status":"live","tier":"essential","bookable":"beach-day tour/transfer + CONANP bracelet or self-drive","source":"https://en.wikipedia.org/wiki/Puerto_Balandra,_Baja_California_Sur","hook":"wade the shallow flats to Baja''s most-photographed rock, the emblem of La Paz","si":"tropical","blurb":"wade the shallow flats to Baja''s most-photographed rock, the emblem of La Paz","commission":"DMC transfer + Viator/GYG affiliate"},{"name":"Kayak / SUP the turquoise flats","si_tag":"tropical","status":"live","tier":"comfort","bookable":"local kayak/SUP rental/tour","source":"https://www.thoroughlytravel.com/balandra-beach-mexico/","hook":"paddle glass-calm, waist-deep water around the coves; low-impact, all-ages","si":"tropical","blurb":"paddle glass-calm, waist-deep water around the coves; low-impact, all-ages","commission":"operator + GYG affiliate"},{"name":"Shallow-water kids'' beach day","si_tag":"family","status":"future","tier":"essential","bookable":"beach-day transfer + bracelet","source":"https://www.thoroughlytravel.com/balandra-beach-mexico/","hook":"near-waveless, waist-deep flats — one of Baja''s safest child-friendly swims","si":"family","blurb":"near-waveless, waist-deep flats — one of Baja''s safest child-friendly swims","commission":"DMC transfer + affiliate"},{"name":"Balandra + Tecolote combo day","si_tag":"family","status":"future","tier":"comfort","bookable":"combined beach-day tour","source":"https://mrplayas.com/la-paz/beaches","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"pair protected Balandra with nearby Playa Tecolote for a full family beach day","si":"family","blurb":"pair protected Balandra with nearby Playa Tecolote for a full family beach day","when":"Nov-Apr","commission":"local operator + Viator affiliate"},{"name":"Sunrise/early-slot photo morning","si_tag":"romance","status":"future","tier":"premier","bookable":"private driver-guide + bracelet","source":"https://www.thoroughlytravel.com/balandra-beach-mexico/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"postcard turquoise + El Hongo before the crowds and heat — couples'' shoot backdrop","si":"romance","blurb":"postcard turquoise + El Hongo before the crowds and heat — couples'' shoot backdrop","when":"Nov-Apr","commission":"Journey Mexico/Amstar DMC + affiliate"}],"faq":[{"q":"How do I get into Balandra, and what does it cost?","a":"Arrive at least 30 minutes before your shift and buy a conservation bracelet — Balandra is not a walk-up-anytime beach. Entry runs in two fixed daily slots (08:00–12:00, 13:00–17:00), capped near 450 visitors each on a first-come basis, with a ~MXN 125 pp/day CONANP bracelet (exemptions for under-12s, seniors and people with disabilities).","source":"thoroughlytravel.com","si_tag":"tropical"},{"q":"When is the best time for photos at El Hongo?","a":"Take the 08:00 morning slot in the cooler Nov–Apr months for the best light and the emptiest sand. Balandra fills its ~450-per-slot cap fastest in peak season and over Mexican holidays, and midday desert glare flattens the turquoise — so the early shift gives couples both the calm water and the postcard color.","source":"thoroughlytravel.com","si_tag":"romance"},{"q":"What''s the real risk to plan for at Balandra?","a":"Sun, heat and the lack of services — not crime. There is scarce shade, no food or water vendors and no lifeguards inside the bay, and hurricane season runs Jun–Nov; bring an umbrella, hydration and reef-safe sunscreen, and carry trip insurance for summer/fall dates.","source":"dossier","si_tag":"safety"}],"seo":{"meta_title":"Balandra Beach La Paz: El Hongo & Entry Rules 2026","meta_description":"Wade the shallow turquoise flats of protected Playa Balandra to El Hongo mushroom rock — timed entry (~450/slot), conservation bracelet, no services. Plan the day.","slug":"balandra-beach-mexico","primary_keyword":"Balandra beach La Paz","long_tail":["Balandra beach entrance fee 2026","Playa Balandra timed entry rules","El Hongo mushroom rock La Paz","Balandra vs Tecolote beach","Balandra shallow water family beach"],"search_language":["en","es-MX"],"local_keywords":["Playa Balandra La Paz horarios","brazalete Balandra CONANP precio","El Hongo de Balandra","playa protegida La Paz aguas someras","Balandra vs Tecolote","Playa Balandra niños familia","cómo llegar a Balandra La Paz"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":{"bin":"freely_bookable","level":"L2","codes":[],"consent_flow":false,"note":"Quintana Roo/Mexico US L2 (Exercise Increased Caution) - freely bookable; MXN currency, USD widely accepted"},"si_checklist_25":{"run_date":"2026-07-31","hits":3,"misses":19,"disregarded":3,"note":"Canonical 25-SI list; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"tropical","name":"tropical","status":"live","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"family","name":"family","status":"future","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"future","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"}],"ultra":[{"name":"Private driver-guide Balandra morning (from La Paz/Los Cabos luxury base)","posture":"no on-beach lodging exists; ultra play is private guide + early-slot + provisioning","price_tier":"luxury","earning":"on application via host / Journey Mexico DMC","virtuoso_value_add":"private guide + chilled provisioning (no vendors) + pairing with Espiritu Santo","mor":"no net-rate resale","source":"https://www.thoroughlytravel.com/balandra-beach-mexico/"}],"source_verified":"2026-07-04","hero":{"query":"Balandra Beach (Playa Balandra), Mexico"},"geo":{"lat":24.32,"lng":-110.33}}'::jsonb, 35),
