insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('chichen-itza-mexico', '10S', 'Chichén Itzá', 'Mexico', 'Chichén Itzá', 'live', 'verified', 'kyoto', 'Yucatán (Mérida & Chichén Itzá)', '{"culture","expedition","wellness"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["UNESCO World Heritage Site + one of the New Seven Wonders; opens 8:00 AM, last entry 4 PM, closes 5 PM","Spring-equinox serpent-shadow (Kukulcan descending El Castillo) ~Mar 20-21, 4:30-5:10 PM; 8,400+ visitors 2026; autumn equinox ~Sep 22-23","Climbing El Castillo BANNED since 2008 (INAH); unauthorized climb fines ~55,760-278,800 MXN (~US$3,200-16,000) as of 2025","Cenote Ik Kil ~3 km away - ~60 m wide, ~40 m deep open sinkhole; entry ~250 MXN (520 w/ buffet); swim/snorkel, no lifeguard","Balankanche grotto - guided >1 km Maya-Toltec ritual cave, ~10 m descent; entrance to the underworld"],"safety":{"emergency":"911","hospital":"rural zone; nearest trauma care Merida (~2 hr W, Star Medica/Clinica de Merida) or Cancun (~2 hr E, Hospiten/Amerimed) or air-evac","advisory_level":"L1","book_enabled":true,"air_access_verified":"yes - MID Merida ~2 hr W or CUN Cancun ~2 hr E; Chichen sits between","heat":"PRIMARY RISK - large open shadeless site in intense Yucatan sun; go at 8:00 AM opening, carry 1.5-2 L water, sun hat + high SPF; heat exhaustion #1 incident risk; equinox afternoons = long standing in heat + crowds","cenote":"Ik Kil = swim/snorkel only, NO lifeguard; provided life jackets (mandatory posture for non-swimmers/children); shower off sunscreen; steep wet stairs. Balankanche = guided dry-cave walk only, not a dive site","dive_no_fly":"Chichen NOT a scuba destination (Ik Kil/Balankanche are swim/walk). Nearest hyperbaric chambers on coast (SSS/DAN Cancun, Playa, Cozumel; SSS Merida) ~2+ hr away; DAN says nearest hospital first","malaria":"effectively none in tourist zone","dengue":"active in Yucatan 2026; chikungunya/Zika circulate - use repellent at grotto/cenote","water":"bottled/purified only","hurricane":"Jun-Nov","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"inflection_curve_start":"late January (spring-equinox bed/tour demand hardens Jan-Feb for the ~Mar 20-21 window)","peak":"dry season Nov-Apr (Dec-Jan busiest w/ Riviera Maya high season); SPRING EQUINOX ~Mar 20-21 is the single event peak (8,400+ visitors 2026, shadow 4:30-5:10 PM)","fire_date":"2027-01-08 (curve-start minus 1-2 wks; fire the spring-equinox campaign before beds/early-entry sell out)","shoulder":"May + Oct; autumn equinox ~Sep 22-23 is a green-window mini-spike","green":"Jun-Sep (extreme heat/humidity, hurricane-season afternoon rain) - go at 8:00 AM opening; sell Ik Kil as heat counterweight","booking_lead":"day-trip/excursion days-to-weeks; EQUINOX exception - book beds + guided early entry months ahead (Jan-Feb) for March","off_season_specials":"green window: anchor Chichen as marquee day-trip inside a Merida hacienda-circuit or Valladolid Pueblo-Magico stay; push autumn equinox as crowd-lighter alt to March","event_peaks":"Spring equinox ~Mar 20-21 (#1); autumn equinox ~Sep 22-23 (#2); Christmas-New Year, Semana Santa; free-Sunday crowds (Mexican nationals/residents)","note":"sharpen on live tracking - confirm 2027 equinox date + exact shadow window + site event rules before firing","sources":["https://yucatanmagazine.com/chichen-itza-equinox/","https://www.exoticca.com/us/blog/witnessing-the-2026-spring-equinox-chichen-itza-teotihuacan-and-beyond/","https://chichenitzamexico.org/entrance-fee/"]},"jewels":[{"name":"Dawn / 8:00 AM early entry to El Castillo","si_tag":"Culture & Heritage","status":"future","tier":"comfort","bookable":"DMC early-entry tour + INAH/CULTUR entry","source":"https://chichenitzamexico.org/entrance-fee/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the ceremonial core empty and cool before the buses; the only way to photograph the Wonder without crowds or midday heat","si":"culture","blurb":"the ceremonial core empty and cool before the buses; the only way to photograph the Wonder without crowds or midday heat","when":"dry season Nov-Apr","commission":"Amstar/Olympus DMC + Viator affiliate (site fees non-commissionable)"},{"name":"Spring-equinox serpent-shadow (Kukulcán descending)","si_tag":"Culture & Heritage","status":"future","tier":"comfort","bookable":"equinox early-entry tour + beds booked Jan-Feb","source":"https://yucatanmagazine.com/chichen-itza-equinox/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the once-a-year engineered light-and-shadow spectacle, 4:30–5:10 PM ~Mar 20–21; the event peak","si":"culture","blurb":"the once-a-year engineered light-and-shadow spectacle, 4:30–5:10 PM ~Mar 20–21; the event peak","when":"dry season Nov-Apr","commission":"DMC + affiliate; base beds via bedbank/consortia"},{"name":"Evening Noches de Kukulcán light-and-sound show","si_tag":"Culture & Heritage","status":"future","tier":"comfort","bookable":"evening ticket + guide (verify seasonal schedule)","source":"https://www.chichenitza.com/tickets","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"after-dark projection-mapping over the ruins, extends the day and the spend","si":"culture","blurb":"after-dark projection-mapping over the ruins, extends the day and the spend","when":"dry season Nov-Apr","commission":"DMC + affiliate"},{"name":"Yaxunáh community-Maya alternative","si_tag":"Culture & Heritage","status":"future","tier":"comfort","bookable":"private community tour (Amigo Tours / Marriott Bonvoy activities)","source":"https://yucatantoday.com/en/yaxunah-a-community-run-paradise/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a living Maya community + quiet archaeological zone just south of Chichén; the responsible, crowd-free counter to the Wonder","si":"culture","blurb":"a living Maya community + quiet archaeological zone just south of Chichén; the responsible, crowd-free counter to the Wonder","when":"dry season Nov-Apr","commission":"private-tour DMC + Viator affiliate"},{"name":"Cenote Ik Kil swim","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","bookable":"entry ~250 MXN + combo day tour","source":"https://cenotetickets.com/blog/en/cenote-ik-kil-entrance-fee-2025/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the iconic ~40 m emerald sinkhole 3 km from the ruins with vine curtains and waterfalls","si":"expedition","blurb":"the iconic ~40 m emerald sinkhole 3 km from the ruins with vine curtains and waterfalls","when":"dry season Nov-Apr","commission":"DMC + Viator affiliate (entry non-commissionable)"},{"name":"Balankanché caves (guided grotto)","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","bookable":"entry + guided cave tour","source":"https://www.chichenitza.com/cenotes/ik-kil-cenote","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":">1 km underworld ritual cave with ancient Maya-Toltec offering chambers, a few km from the ruins — the archaeology-under-the-earth complement to the surface city","si":"expedition","blurb":">1 km underworld ritual cave with ancient Maya-Toltec offering chambers, a few km from the ruins — the archaeology-under-the-earth complement to the surface city","when":"dry season Nov-Apr","commission":"DMC + affiliate"},{"name":"Hacienda Chichén stay + Yaxkin Spa","si_tag":"Wellness","status":"future","tier":"premier","bookable":"FIT / consortia direct","source":"https://www.haciendachichen.com/","timing":"year-round","timing_type":"ALWAYS-ON","si":"wellness","when":"year-round","commission":"host/Fora-Virtuoso where property participates; commission on application"}],"faq":[{"q":"When is the equinox serpent-shadow and how do I see it?","a":"The spring equinox around March 20–21 is the peak, when seven triangles of light descend the north staircase of El Castillo between roughly 4:30 and 5:10 PM and Kukulcán appears to slither toward the stone serpent-head — the Maya engineered it more than a thousand years ago. It drew 8,400 people in 2026; the autumn equinox (~Sep 22–23) is the quieter alternative. Book beds and guided early entry in January–February.","source":"yucatanmagazine.com, 2026-07-06","si_tag":"culture"},{"q":"Can you still climb the pyramid at Chichén Itzá?","a":"No — climbing El Castillo has been banned since 2008 by INAH to protect the structure, and as of 2025 unauthorized climbing draws fines of roughly US$3,200–16,000. You photograph the Wonder from the plaza at the 8:00 AM opening, before the buses and the heat.","source":"chichenitza.com, 2026-07-06","si_tag":"culture"},{"q":"Can beginners and kids swim Cenote Ik Kil?","a":"Yes — it is a surface swim, not a dive. Ik Kil is a ~40 m-deep open sinkhole 3 km from the ruins with provided life jackets (mandatory posture for non-swimmers and children) and no lifeguard, so shower off sunscreen first and take the steep wet stairs carefully. Entry is 250 MXN.","source":"cenotetickets.com, 2026-07-06","si_tag":"expedition"},{"q":"Where do you actually stay at Chichén Itzá?","a":"On-site the market is thin but premium — two heritage hotels: Hacienda Chichén (a restored 16th-c. hacienda on a 200-ha private jungle reserve with the Yaxkin Maya-healing spa) and the adjacent Mayaland. Most travelers base at Valladolid (~40 min) or the Mérida hacienda circuit (~2 hr) and day-trip the ruins.","source":"haciendachichen.com, 2026-07-06","si_tag":"wellness"},{"q":"What''s the real risk to plan for at Chichén Itzá?","a":"Extreme heat and sun, not crime. The ceremonial core is a large, open, shadeless site in intense Yucatán sun, and heat exhaustion is the #1 incident risk — enter at the 8:00 AM opening, carry 1.5–2 L of water per person, wear a sun hat and high SPF, and plan a midday exit. On equinox afternoons you stand in heat among thousands, so hydrate and hold position early.","source":"exoticca.com, 2026-07-06","si_tag":"safety"},{"q":"How far is medical care from Chichén Itzá?","a":"Roughly 2 hours either direction — the zone is rural. The nearest full trauma care is Mérida (~2 hr west, Star Médica / Clínica de Mérida) or Cancún (~2 hr east, Hospiten / Amerimed), so carry travel-medical and evacuation insurance.","source":"chichenitzamexico.org, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Chichén Itzá 2026: Equinox Serpent Shadow, Ik Kil & Fees","meta_description":"Chichén Itzá is a New Wonder — see the spring-equinox serpent shadow (~Mar 20–21), swim Cenote Ik Kil and explore Balankanché caves. Fees (~697 MXN), hours, no-climb rule, safety.","slug":"chichen-itza-mexico","primary_keyword":"Chichén Itzá","long_tail":["Chichén Itzá spring equinox 2026 serpent shadow","Chichén Itzá entrance fee 2026","can you climb Chichén Itzá El Castillo","Cenote Ik Kil near Chichén Itzá","Balankanché caves","Hacienda Chichén heritage stay","Chichén Itzá day trip from Cancún Mérida"],"search_language":["en","es-MX"],"local_keywords":["Chichén Itzá equinoccio","serpiente de luz Kukulcán El Castillo","precio entrada Chichén Itzá 2026","no se puede subir El Castillo","Cenote Ik Kil Chichén Itzá","grutas de Balankanché","Chichén Itzá desde Cancún Mérida","Hacienda Chichén hospedaje"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culture","status":"future"},{"si":"expedition","status":"live"},{"si":"wellness","status":"future"}],"ultra":[{"name":"Hacienda Chichen Resort & Yaxkin Spa","tier":"premier-luxury boutique heritage (straight - extraordinary location/story, not 5-star palace)","why":"sleep at the foot of the Wonder; restored 16th-c. hacienda, 200-ha private jungle reserve, Maya-healing spa","earning":"FIT/consortia (Fora/Virtuoso where property participates), commission on application","mor":"host MoR on base-stay + private-tour side; site fees non-commissionable","source":"https://www.haciendachichen.com/"},{"name":"Chable Yucatan (Merida circuit, ~2 hr W) - nearest TRUE ultra","tier":"ultra-luxury (Leading Hotels of the World)","why":"200-yr San Antonio hacienda, 750 acres, spa beside a sacred cenote, ~30 min from MID; base for private-guided Chichen ultra day excursion","earning":"FIT/consortia (Virtuoso/Fora), commission on application","mor":"host MoR on stay + private tour","source":"https://www.lhw.com/hotel/Chable-Yucatan-Chochola-Merida-Mexico"}],"source_verified":"2026-07-06","hero":{"query":"Chichén Itzá, Mexico"},"geo":{"lat":20.6843,"lng":-88.5678}}'::jsonb, 45),
  ('chiloe-island-chile', '10S', 'Chiloé Island & the Chilean Lake District', 'Chile', 'Stilt houses, wooden churches, fog', 'live', 'verified', 'mountainValley', 'Lakes, Patagonia & Easter Island', '{"expedition","romance","culture"}', '{}', '{"essential","premier","luxury"}', null, null, '{"key_facts":null,"safety":{"emergency":"131","emergency_all":{"ambulance_samu":"131","police_carabineros":"133","fire_bomberos":"132"},"advisory_level":"L2","advisory_why":"crime + civil unrest concentrated in central Santiago; Araucania/Biobio state-of-emergency is mainland, well north of Chiloe","advisory_source":"travel.state.gov, updated 2026-05-20, accessed 2026-07-07","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"maritime_headline":"sea + weather is the real risk: cold-water/swell on Punihuil boats (life vests mandatory), rough ferry crossings, exposed sea-cliff hikes, cold/rain exposure year-round","wet_weather_driving":"self-drive island; frequent rain/fog, narrow rural roads, ferry timing — drive to conditions","water":"Castro/Ancud tap generally potable; rural/small-island varies — note, not guaranteed","evac_chain":"Castro/Ancud clinic -> Puerto Montt regional hospital (via ferry/road or air) -> Santiago; travel+medical insurance strongly indicated","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/chile","read":"2026-08-19","page_updated":"2026-08-18T23:18:12+01:00"}},"timing":{"peak":"Dec-Mar (austral summer — drier; penguin boats Sep-Mar, most penguins Dec-Jan)","shoulder":["Oct-Nov","Apr"],"wet_moody_offseason":"May-Sep (penguin boats stopped; fog/rain — a genuine draw for some; fill-the-beds)","booking_window":"luxe lodge + peak palafito-boutique months ahead; day-tours/penguin boats last-minute walk-up","inflection":"penguin season opens (Sep) + Southern-summer bookings firm for Dec-Mar","fire_date":"mid-to-late August (curve-start minus 1-2 weeks) for Dec-Mar inventory","pairing":"commonly attached to Torres del Paine / Patagonia + Lake District (Puerto Varas)"},"jewels":[{"name":"Castro palafitos + Iglesia San Francisco de Castro","si_tag":"culture","tier":"premier","source":"https://www.swoop-patagonia.com/chile/lake-district/chiloe/castro","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the island''s largest cluster of stilt-houses framing the yellow-and-mauve neo-Gothic Iglesia San Francisco, a UNESCO church with a twin-towered painted façade","si":"culture","blurb":"the island''s largest cluster of stilt-houses framing the yellow-and-mauve neo-Gothic Iglesia San Francisco, a UNESCO church with a twin-towered painted façade","when":"Dec-Mar","commission":"Castro heritage walk + palafito-boutique stay + guided church visit (DMC/local)"},{"name":"UNESCO wooden-church circuit (Achao / Tenaún / Dalcahue)","si_tag":"culture","tier":"essential","source":"https://gopatagonic.com/chiloe-churches-route/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"Santa María de Loreto de Achao on Quinchao island; Nuestra Señora del Patrocinio de Tenaún with its two painted front stars and bluish tone","si":"culture","blurb":"Santa María de Loreto de Achao on Quinchao island; Nuestra Señora del Patrocinio de Tenaún with its two painted front stars and bluish tone","when":"year-round","commission":"guided/self-drive church circuit (ferry island-hop) via DMC"},{"name":"Traditional curanto en hoyo","si_tag":"culture","tier":"essential","source":"https://en.wikipedia.org/wiki/Curanto","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the pit-cooked shellfish-meat-potato feast under nalca leaves and turf, an 11,000-year-old whole-community tradition","si":"culture","blurb":"the pit-cooked shellfish-meat-potato feast under nalca leaves and turf, an 11,000-year-old whole-community tradition","when":"Dec-Mar","commission":"DMC/lodge curanto experience or Dalcahue market kitchens"},{"name":"Chilote mythology / the Caleuche","si_tag":"culture","tier":"essential","source":"https://en.wikipedia.org/wiki/Chilote_mythology","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the archipelago''s living folklore of the Caleuche ghost ship crewed by the drowned, La Pincoya the sea-goddess whose dance decides the catch","si":"culture","blurb":"the archipelago''s living folklore of the Caleuche ghost ship crewed by the drowned, La Pincoya the sea-goddess whose dance decides the catch","when":"Dec-Mar","commission":"guided folklore walk / heritage-experience add-on"},{"name":"Dalcahue Sunday market + Isla Quinchao","si_tag":"culture","tier":"essential","source":"https://blueskylimit.com/chiloe-chile-exploring-dalcahues-sunday-artisan-market-and-its-classic-church/","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the waterfront feria artesanal on Pedro Montt and the short ferry hop to Quinchao for Curaco de Vélez and Achao''s landmark church","si":"culture","blurb":"the waterfront feria artesanal on Pedro Montt and the short ferry hop to Quinchao for Curaco de Vélez and Achao''s landmark church","when":"Dec-Mar","commission":"self-drive + ferry or DMC island-hop day"},{"name":"Ancud + Fuerte San Antonio","si_tag":"culture","tier":"essential","source":"https://www.tripadvisor.com/Attraction_Review-g317803-d7018908-Reviews-Fuerte_San_Antonio-Ancud_Isla_Chiloe_Los_Lagos_Region.html","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the mainland-facing gateway town with the 17th-century Spanish coastal fort, sunset over the sea, and the closest base for the Puñihuil boats","si":"culture","blurb":"the mainland-facing gateway town with the 17th-century Spanish coastal fort, sunset over the sea, and the closest base for the Puñihuil boats","when":"Dec-Mar","commission":"DMC/self-drive Ancud-Punihuil day"},{"name":"Puñihuil penguin colony (Humboldt + Magellanic side by side)","si_tag":"expedition","tier":"essential","source":"https://www.swoop-patagonia.com/chile/lake-district/chiloe/punihuil-penguin","hook":"the only place on Earth the two species nest together, on three protected islets; small-boat encounters Sep–Mar, peak Dec–Jan","si":"expedition","blurb":"the only place on Earth the two species nest together, on three protected islets; small-boat encounters Sep–Mar, peak Dec–Jan","commission":"community boat concession (Ecoturismo Punihuil) or DMC bundle (Sep-Mar)"},{"name":"Chiloé National Park + Muelle de las Almas","si_tag":"expedition","tier":"essential","source":"https://gopatagonic.com/visit-chiloe-national-park-and-muelle-de-las-almas/","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the wild Pacific-side park at Cucao and the cinematic cliff-top Dock of Souls boardwalk over the Bay of Cucao","si":"expedition","blurb":"the wild Pacific-side park at Cucao and the cinematic cliff-top Dock of Souls boardwalk over the Bay of Cucao","when":"Dec-Mar","commission":"guided/self-drive Cucao day + park entry"},{"name":"Palafito-boutique stay over the water (Castro, Gamboa)","si_tag":"romance","tier":"premier","source":"https://www.chilevacay.com/chiloe-island-palafitos-and-folklore/","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a restored stilt-house design hotel with the tide beneath the floor and the church across the water; the signature slow-romance Chiloé stay","si":"romance","blurb":"a restored stilt-house design hotel with the tide beneath the floor and the church across the water; the signature slow-romance Chiloé stay","when":"Dec-Mar","commission":"palafito-boutique direct/OTA or MoR villa rung"},{"name":"Tierra Chiloé (Rilán peninsula, all-inclusive lodge)","si_tag":"romance","tier":"luxury","source":"https://tierrachiloe.com/stay/rilan-room/","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dec-Mar","commission":"consortium/preferred-partner (Virtuoso/Fora) or direct/MoR"}],"faq":[{"q":"When can you see penguins at Puñihuil, Chiloé?","a":"Boats run September to March, with the most penguins in December–January. That window exists because the Humboldt and Magellanic penguins — the only colony on Earth where the two species nest side by side — are ashore to mate, nest and incubate then, and return to sea by late March, when the boats stop. The colony sits on three islets ~27 km southwest of the Gulf of Ancud, reached by small boat with no landing, as it is a National Monument.","source":"swoop-patagonia.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"What are Chiloé''s UNESCO wooden churches?","a":"They are 16 of some 70 timber churches built under the Jesuits'' 17th-century \"Circular Mission\" and continued by the Franciscans, inscribed on the UNESCO World Heritage List. They matter because they are the exceptional expression of the Chilota school of nail-free timber architecture — joined with wooden pegs, not nails — spread across Achao, Castro, Tenaún, Dalcahue, Quinchao and more.","source":"whc.unesco.org, Accessed 2026-07-07","si_tag":"culture"},{"q":"Where do you stay for a romantic Chiloé trip?","a":"Stay in a restored palafito-boutique over the water in Castro''s Gamboa neighbourhood — the signature slow-romance base. It works because Castro, founded in 1567, holds the island''s greatest concentration of stilt-houses, putting the tide beneath the floor and a UNESCO church across the water.","source":"swoop-patagonia.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"Is there an all-inclusive lodge on Chiloé?","a":"Yes — Tierra Chiloé on the Rilán peninsula, the archipelago''s only true all-inclusive apex. It bundles lodging, all meals, open bar and daily guided excursions across 24 rooms/suites, is a National Geographic Unique Lodges of the World member, and is the island''s only hotel with its own boat (the *Williche*) for private navigation. Elsewhere Chiloé is B&B, palafito-boutique and cabaña country.","source":"tierrachiloe.com, Accessed 2026-07-07","si_tag":"all_inclusive-model"},{"q":"What''s the real risk to plan for on Chiloé?","a":"The sea and the weather, not people. Chiloé is a wet, foggy, wind-exposed maritime environment: the Puñihuil boats run open water with swell and cold water, the Chacao Channel ferry can be rough, and cold-water immersion is dangerous year-round. Wear the provided life vests, follow crew calls, accept weather cancellations, and never board small boats against a crew''s weather judgment.","source":"swoop-patagonia.com, Accessed 2026-07-07","si_tag":"safety"},{"q":"Is the Puñihuil penguin boat dangerous?","a":"It is low-risk when done right: a ~40-minute crew-operated small-boat run around the three islets (no landing), with life vests mandatory and trips weather-cancellable and Sep–March only. It is never a self-launch — book through the community concession or a DMC bundle. The real hazards are open-water swell and cold water, which the crew manages.","source":"swoop-patagonia.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Chiloé Island & the Chilean Lake District — Palafitos, UNESCO Churches, Puñihuil Penguins & Curanto | TravelWell","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"es-CL","local_keywords":["qué hacer en Chiloé","palafitos Castro","iglesias de Chiloé","pingüinos Puñihuil","circuito de iglesias de Chiloé","curanto en hoyo Chiloé","Muelle de las Almas Cucao","cómo llegar a Chiloé ferry Pargua","mitología de Chiloé Caleuche"],"hreflang":["en","es-CL"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Tierra Chiloe","type":"all-inclusive stilt-style lodge, Rilan peninsula (24 rooms, spa, own boat; NatGeo Unique Lodges)","earning":"all-inclusive luxe commission band","mor":"where contracted","tier":"luxury"},{"name":"Palafito-boutique hotels (Castro / Gamboa)","type":"restored stilt-house design hotels over the tide","earning":"boutique-hotel commission","mor":"where terms allow","tier":"premium-luxe"},{"name":"Refugia Chiloe (OCIO-territorial-style small lodge)","type":"intimate design lodge, local-food + curanto program, guided excursions","earning":"premium-lodge commission","mor":"where contracted","tier":"luxe"}],"source_verified":null,"hero":{"query":"Chiloé Island & the Chilean Lake District, Chile"},"geo":{"lat":-42.4823,"lng":-73.7626}}'::jsonb, 46),
  ('coba-mexico', '10S', 'Cobá', 'Mexico', 'Cobá ruins', 'live', 'verified', 'kyoto', 'Quintana Roo (Cancún & Riviera Maya)', '{"culture","expedition","family"}', '{}', '{"essential"}', 'essential', null, '{"key_facts":["Ancient Maya city deep in the jungle ~47 km NW of Tulum; opens daily 8:00 AM","Nohoch Mul climbing REOPENED Dec 8, 2025 - new wooden staircase to 42 m (138 ft) summit","Climb 8:00-3:30, groups of 15, 15-min summit limit; closed-toe grippy shoes mandatory","Three cave cenotes: Choo-Ha (shallow), Tankach-Ha (deep, jump platforms), Multun-Ha","Vast site - bikes/pedicabs are the usual way to explore"],"safety":{"emergency":"911","hospital":"small village; nearest trauma care Tulum/Playa del Carmen/Cancun private hospitals or air-evac","advisory_level":"L2","malaria":"effectively none in tourist/inland-tour zone","dengue":"active - Quintana Roo among highest-activity states 2026; chikungunya/Zika circulate; jungle - use repellent","water":"bottled/purified only; carry ample water - heat/hydration is the main climb risk","hurricane":"Jun-Nov (heavy rain)","ruins":"heat/hydration primary risk; closed-toe grippy shoes mandatory for Nohoch Mul; go early","cenote":"cavern - shower off sunscreen before entry; safety ropes; life jacket for non-swimmers/children; Tankach-Ha deep with jump platforms","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"type":"inland archaeological day-trip - no overnight lodging market; based from Tulum/Playa","peak":"Nov-Apr dry season (fewer mosquitoes, less heat/humidity); April standout; Dec-Jan busier (Riviera Maya high season)","shoulder":"May + Oct","green":"Jun-Sep (jungle heat/humidity peak, hurricane-season afternoon rain) - go at 8:00 AM opening","demand_driver":"Nohoch Mul climb REOPENED Dec 8, 2025 (42 m, groups of 15, 15-min limit, closed-toe shoes); VERIFY still open at booking","booking_window_lead_time":"day-trip/excursion booking (days to weeks); no overnight market; bed-night lead time sits on the Tulum/Playa base","out_of_season_fill_the_beds":"N/A on-site (no beds); anchor Coba day trip to a coastal Tulum/Playa/Riviera Maya stay; sell cave-cenote swims as heat counterweight","holiday_event_peaks":"Christmas-New Year, Semana Santa (arrive 8:00 AM); post-reopening Nohoch Mul climb demand","campaign_start_trigger":"fire inside the coastal booking cycle (Aug-Oct winter peak; Feb-Mar shoulder); lead with ''Nohoch Mul is climbable again''","sources":["https://www.besttime2travel.com/coba","https://www.chichenitza.com/blog/nohoch-mul-the-tallest-temple-in-coba","https://www.mexicotravelandleisure.com/blog/coba-ruins-guide/"]},"jewels":[{"name":"Nohoch Mul pyramid climb","si_tag":"Culture & Heritage","status":"future","tier":"essential","bookable":"INAH entry + guided ruins tour","source":"https://www.chichenitza.com/blog/nohoch-mul-the-tallest-temple-in-coba","timing":"Nov-Apr dry season","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"one of the tallest Maya pyramids, reopened Dec 2025 via protective wooden staircase; jungle-canopy summit view","si":"culture","blurb":"one of the tallest Maya pyramids, reopened Dec 2025 via protective wooden staircase; jungle-canopy summit view","when":"Nov-Apr dry season","commission":"Amstar/Olympus DMC + Viator affiliate (entry non-commissionable)"},{"name":"Coba archaeological zone by bike/pedicab","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","bookable":"guided tour + on-site bike/pedicab rental","source":"https://www.mexicotravelandleisure.com/blog/coba-ruins-guide/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"sprawling jungle Maya city linked by ancient white sacbé roads; cover it by bicycle or pedicab","si":"expedition","blurb":"sprawling jungle Maya city linked by ancient white sacbé roads; cover it by bicycle or pedicab","when":"year-round","commission":"DMC + Viator affiliate"},{"name":"Choo-Ha cave cenote","si_tag":"Family","status":"future","tier":"essential","bookable":"cenote entry + combo tour","source":"https://bucketlistbri.com/coba-cenotes/","timing":"Nov-Apr dry season","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"shallow, stalactite-filled cavern; the gentlest of the three — good family/first-cenote swim","si":"family","blurb":"shallow, stalactite-filled cavern; the gentlest of the three — good family/first-cenote swim","when":"Nov-Apr dry season","commission":"DMC + Viator affiliate (entry non-commissionable)"},{"name":"Tankach-Ha cave cenote","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","bookable":"cenote entry + combo tour","source":"https://www.mexicocenotesandruins.com/cenote-tankach-ha-coba/","timing":"Nov-Apr dry season","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"deep cavern with 5 m & 10 m jump platforms and dramatic stalactites","si":"expedition","blurb":"deep cavern with 5 m & 10 m jump platforms and dramatic stalactites","when":"Nov-Apr dry season","commission":"DMC + Viator affiliate"},{"name":"Multun-Ha cave cenote","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","bookable":"cenote entry + combo tour","source":"https://bucketlistbri.com/coba-cenotes/","timing":"Nov-Apr dry season","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the third, quieter cave cenote in the Cobá cluster; cool clear underground pool","si":"expedition","blurb":"the third, quieter cave cenote in the Cobá cluster; cool clear underground pool","when":"Nov-Apr dry season","commission":"DMC + Viator affiliate"}],"faq":[{"q":"What''s the real risk to plan for at Cobá?","a":"Heat and hydration, plus mosquitoes — not crime. Cobá is open, humid jungle with a 42 m pyramid climb, so the main risk is heat exhaustion: go at the 8:00 AM opening, carry ample water and sun protection. Dengue is active — Quintana Roo is among Mexico''s highest-activity states in 2026 — so use repellent; there is effectively no malaria.","source":"nomadoc.com.mx / mexicotravelandleisure.com, 2026-07-04","si_tag":"safety"},{"q":"Can you climb Nohoch Mul in 2026?","a":"Yes — climbing reopened on December 8, 2025 after roughly six years closed, so verify it is still open at booking. A new wooden staircase now protects the original 120 stone steps up to the 42 m (138 ft) summit, one of the tallest Maya pyramids, with a jungle-canopy view from the top. Climb window is 8:00 AM–3:30 PM.","source":"chichenitza.com, 2026-07-04","si_tag":"culture"},{"q":"How do you get around Cobá, and how far is it from the coast?","a":"By bicycle or pedicab — the site is too vast to walk comfortably. Cobá sits ~47 km (29 mi) NW of Tulum, so it is almost always done as a guided day trip from a Tulum, Playa del Carmen or Riviera Maya base; it has essentially no overnight lodging market of its own. The zone opens at 8:00 AM.","source":"xamanhaconnections.com / mexicotravelandleisure.com, 2026-07-04","si_tag":"expedition"},{"q":"Are the Cobá cenotes good for kids?","a":"Yes — the cave cenotes make an ideal cool-off after the ruins. Choo-Ha is shallow and gentle, the best first cenote for children; all three have safety ropes and provided life jackets. Shower off sunscreen before entering to protect the water, and take the steep, wet stone stairs carefully (Tankach-Ha is ~83 steps down).","source":"bucketlistbri.com, 2026-07-04","si_tag":"family"},{"q":"When is the best time to visit Cobá?","a":"November–April, the dry season, is best — fewer mosquitoes, lower humidity and less heat for the jungle climb, with April the standout month. Whatever the season, arrive at the 8:00 AM opening to beat both the heat and the crowds; the June–September green season brings peak jungle heat and hurricane-season afternoon rain.","source":"besttime2travel.com / mexicotravelandleisure.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Cobá Ruins & Cenotes: Climb Nohoch Mul","meta_description":"Cobá is inland Maya jungle — climb the 42 m Nohoch Mul pyramid (reopened Dec 2025) and swim the Choo-Ha, Tankach-Ha and Multun-Ha cave cenotes. When, fees and safety.","slug":"coba-mexico","primary_keyword":"Cobá ruins","long_tail":["Nohoch Mul climbing 2026","Coba cenotes Choo-Ha Tankach-Ha","Coba ruins from Tulum","tallest Maya pyramid Quintana Roo","Coba bike pedicab jungle ruins"],"search_language":["en","es-MX"],"local_keywords":["ruinas de Cobá","subir Nohoch Mul Cobá reabierto","pirámide más alta maya Quintana Roo","cenotes Cobá Choo-Ha Tankach-Ha Multun-Ha","Cobá desde Tulum","tour Cobá y cenotes","bicicleta bicitaxi ruinas de Cobá"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culture","status":"future"},{"si":"expedition","status":"live"},{"si":"family","status":"future"}],"ultra":[],"source_verified":"2026-07-04","hero":{"query":"Cobá, Mexico"},"geo":{"lat":20.495,"lng":-87.736}}'::jsonb, 47),
  ('colchagua-valley-chile', '10S', 'Colchagua Valley & Chilean Wine Country', 'Chile', 'Colchagua Valley & Chilean Wine Country', 'live', 'verified', 'restaurant', 'Santiago & Central Valley Wine', '{"culinary","romance"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":null,"safety":{"emergency":"131","emergency_all":{"ambulance":"131","fire":"132","police":"133"},"advisory_level":"L2","advisory_reissued":"2026-05-20","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"air_access_note":"via Santiago SCL, ~2-3 hr drive to Santa Cruz","key_safety_line":"drink-driving — always use a designated driver or guided wine tour","trauma_pathway":"Santa Cruz / San Fernando clinics -> Santiago evac (~2-3 hr)","water":"potable","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/chile","read":"2026-08-19","page_updated":"2026-08-18T23:18:12+01:00"}},"timing":{"peak_windows":["Fiesta de la Vendimia — March 6-8, 2026 (Santa Cruz)","Autumn/harvest — March-May","Spring — October-November","Summer — December-February"],"inflection":["late February (pre-Vendimia climb)","late September (spring travel)"],"trough":"winter June-August (off-season fill)","fire_date":"2026-02-15 (mid-February — curve-start minus 1-2 weeks, ahead of Vendimia)"},"jewels":[{"name":"Viña Montes feng-shui cellar (Apalta)","si_tag":"Culinary/Wine","tier":"premier","source":"https://www.wanderlustchloe.com/top-places-to-go-wine-tasting-in-the-colchagua-valley-vina-montes/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"Built in 2004 on feng-shui principles; wooden path over a lagoon, 800 oak barrels in a semicircle serenaded by Gregorian chant","si":"Culinary/Wine","blurb":"Built in 2004 on feng-shui principles; wooden path over a lagoon, 800 oak barrels in a semicircle serenaded by Gregorian chant","when":"year-round","commission":"estate visit + lunch via DMC/AOR"},{"name":"Lapostolle / Clos Apalta biodynamic winery","si_tag":"Culinary/Wine","tier":"luxury","source":"https://southamericawineguide.com/winery/lapostolle-clos-apalta-winery/","si":"Culinary/Wine","commission":"premium tasting + lunch via AOR"},{"name":"Viu Manent horse-drawn carriage (century-old Malbec)","si_tag":"Culinary/Wine","tier":"comfort","source":"https://viumanent.cl/en/visitenos/tour-degustacion/tour-en-carruaje/","hook":"Family winery, wine-tourism pioneer since 1995; carriage or e-bike rides through the San Carlos vineyard where vines top 100 years","si":"Culinary/Wine","blurb":"Family winery, wine-tourism pioneer since 1995; carriage or e-bike rides through the San Carlos vineyard where vines top 100 years","commission":"tour+tasting+lunch via DMC/AOR"},{"name":"Carmenère vertical tasting","si_tag":"Culinary/Wine","tier":"premier","source":"https://southamericawineguide.com/winery/lapostolle-clos-apalta-winery/","hook":"A multi-vintage Carmenère flight at Lapostolle or Montes — the grape''s Chilean redemption story in a glass","si":"Culinary/Wine","blurb":"A multi-vintage Carmenère flight at Lapostolle or Montes — the grape''s Chilean redemption story in a glass","commission":"premium tasting upsell via AOR"},{"name":"Colchagua Wine Train (Tren del Vino)","si_tag":"Culture/Heritage","tier":"comfort","source":"https://www.welcomechile.com/rancagua/wine-train.html","hook":"Antique rail cars — a 1913 coal-fired steam engine among the last built in Chile","si":"culture","blurb":"Antique rail cars — a 1913 coal-fired steam engine among the last built in Chile","commission":"packaged full-day tour via DMC"},{"name":"Santa Cruz Plaza + Museo de Colchagua","si_tag":"Culture/Heritage","tier":"comfort","source":"https://www.thetravelmavens.com/riding-chiles-wine-train-to-the-colchagua-valley.html","hook":"The Colchagua Museum is the largest private collection in Chile","si":"culture","blurb":"The Colchagua Museum is the largest private collection in Chile","commission":"museum non-commissionable; hotel via AOR/bedbank"},{"name":"Harvest grape-stomp (Fiesta de la Vendimia, March)","si_tag":"romance","tier":"premier","source":"https://www.cavacolchagua.cl/en/2026/02/19/vendimia-de-colchagua-2026/","hook":"Roll up the sleeves and stomp grapes in wooden vats amid parades and plaza music — a once-a-year, deeply photogenic couple''s experience","si":"romance","blurb":"Roll up the sleeves and stomp grapes in wooden vats amid parades and plaza music — a once-a-year, deeply photogenic couple''s experience","commission":"Vendimia-timed lodge package via AOR"},{"name":"Vineyard cycling loop (Santa Cruz radius)","si_tag":"expedition","tier":"essential","source":"https://talesfromthelens.com/cycling-wine-tasting-colchagua-valley-chile/","hook":"Four to five quality wineries within 10 km, bikes under ~€7/24h — a self-paced tasting loop on two wheels","si":"expedition","blurb":"Four to five quality wineries within 10 km, bikes under ~€7/24h — a self-paced tasting loop on two wheels","commission":"bike rental + guided cycling day via DMC"},{"name":"Dawn hot-air balloon over the vines","si_tag":"expedition","tier":"premier","source":"https://produncan.cl/en/discover-santa-cruz-the-heart-of-the-colchagua-valley/","hook":"Panoramic valley flight ending in a wine toast and breakfast","si":"expedition","blurb":"Panoramic valley flight ending in a wine toast and breakfast","commission":"operator booking via DMC/AOR"},{"name":"Horseback ride through the vineyards","si_tag":"expedition","tier":"comfort","source":"https://www.andbeyond.com/places-to-stay/south-america/chile/wine-country/vik-hotel/","hook":"Estate rides at Viu Manent, Vik, and Clos Apalta Residence across vines and foothills","si":"expedition","blurb":"Estate rides at Viu Manent, Vik, and Clos Apalta Residence across vines and foothills","commission":"estate experience or lodge inclusion via AOR"}],"faq":[{"q":"When is the best time to visit Colchagua for wine?","a":"March to May (autumn) is the named ideal window for wine tourism, because harvest activity, color on the vines, and comfortable temperatures line up together. The signature event is the Fiesta de la Vendimia in Santa Cruz, which in 2026 runs March 6, 7, and 8 — the single highest-demand window, so book far ahead.","source":"colchaguawinetours.com, 2026-07-07","si_tag":"culinary"},{"q":"Is Colchagua good for a honeymoon?","a":"Yes — the load-bearing draw here is wine-estate lodging built for two. Clos Apalta Residence puts 10 lodgings on a 1,235-acre reserve with full board, and adjacent Viña Vik offers 22 titanium-clad suites over a lagoon, both with fireplaces, private terraces, and paired estate wines. A honeymoon here is deliberately slow.","source":"relaischateaux.com, 2026-07-07","si_tag":"romance"},{"q":"Can you cycle between the wineries?","a":"Yes, and it''s the valley''s signature soft-adventure. Bikes rent for under about €7 per 24 hours, and four to five quality wineries sit within a 10 km radius of Santa Cruz, making a self-paced tasting loop feasible in daylight — provided the rider driving stays untasted, wears a helmet, and carries water.","source":"talesfromthelens.com, 2026-07-07","si_tag":"expedition"},{"q":"What''s the single biggest safety risk in Colchagua?","a":"Drink-driving — this is the defining operational rule. Tastings run all day, so never self-drive between wineries; use a designated driver or a guided wine tour, which is illegal to skip above Chile''s low BAC limit. Local clinics in Santa Cruz and San Fernando stabilize; serious cases evacuate to Santiago, roughly 2–3 hours away.","source":"colchaguawinetours.com, 2026-07-07","si_tag":"safety"},{"q":"Are the hot-air balloon and horseback add-ons dangerous?","a":"Low risk when booked right — both are guided by definition. Dawn balloon flights (e.g., Heu''Tour) are weather-dependent, so fly only with a licensed, insured operator and confirm the cancellation-for-wind policy; estate horseback rides use helmets and guides. Confirm travel-medical and evac coverage first, since serious cases evacuate to Santiago (~2–3 hr); ambulance is 131.","source":"produncan.cl, 2026-07-07","si_tag":"safety"}],"seo":{"search_language":"es-CL","meta_title":"Colchagua Valley, Chile — Wine Country Travel Guide (Santa Cruz, Apalta & the Wineries) | TravelWell.World","local_keywords":["Valle de Colchagua viñas","ruta del vino Colchagua","Vendimia Santa Cruz","viña Montes Apalta","tren del vino Colchagua","Museo de Colchagua","Carménère Colchagua"],"hreflang":["en","es-CL"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","primary_keyword":"Colchagua Valley & Chilean Wine Country"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culinary","status":"live"},{"si":"romance","status":"live"}],"ultra":[{"name":"Clos Apalta Residence","affiliation":"Relais & Châteaux","earning":"advisor commission on FIT + full-board; Fora/Virtuoso-eligible via R&C","mor":"hotel/host","tier":"$$$$$"},{"name":"Viña Vik","affiliation":"Relais & Châteaux (Millahue, adjacent)","earning":"advisor commission; R&C / luxury-consortia eligible","mor":"hotel/host","tier":"$$$$$"},{"name":"Noi Blend Colchagua","affiliation":"boutique-luxury","earning":"advisor commission on FIT; consortia-adjacent","mor":"host/hotel","tier":"premier"}],"source_verified":null,"hero":{"query":"Colchagua Valley & Chilean Wine Country, Chile"},"geo":{"lat":-34.6413,"lng":-71.366}}'::jsonb, 48),
  ('colonia-del-sacramento-uruguay', '10S', 'Colonia del Sacramento, Uruguay', 'Uruguay', 'Portuguese cobblestones, a lighthouse over the river, Buenos Aires', 'live', 'verified', 'kyoto', 'Montevideo & The Atlantic Coast', '{"culture","romance","culinary"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_level":"L2","advisory_updated":"2025-05-07","advisory_reason":"crime (property + some violent) concentrated in Montevideo, Canelones, Maldonado, Rivera — not Colonia","book_enabled":true,"consent_flow":false,"bin":"freely bookable (L2)","air_access_verified":true,"air_access_note":"Montevideo Carrasco (MVD) + ~2.5-hr road transfer, or Buenos Aires day-ferry ~1–3 hr (Buquebus / Colonia Express)","ferry_border_flag":"BA↔Colonia is an Argentina→Uruguay international crossing — clear immigration at terminal, arrive 1.5–2 hr early, passport required","trauma":"local Colonia clinic/hospital for routine + stabilization; severe trauma escalates by road (~2.5 hr) to Montevideo + international evac; carry medical/evac insurance","crime_note":"Colonia reads calm vs. Montevideo national profile; standard small-town care in ferry-terminal crush + after dark","cobblestone_footing":"uneven 300-yr cobbles, slick when wet — closed gripped footwear; most common minor injury","water":"potable","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/uruguay","read":"2026-08-19","page_updated":"2025-12-10T13:00:39+00:00"}},"timing":{"peak":"summer Dec–Feb (~27 °C days) + spring/fall shoulders (Sep–Nov, Mar–May, ~15–22 °C)","inflection":"Buenos Aires attach — Colonia demand rides the BA/Montevideo curve; thin overnight inventory + summer ferry seats fill early","fire_date":"curve-start minus 1–2 weeks — early–mid Nov for summer; ~2 wks ahead of shoulder start; highest-yield = fire on the traveler''s confirmed BA/Montevideo dates","off_season_fill":"winter Jun–Aug (~8–15 °C) — slow-travel romance overnights + Carmelo indoor-cellar wine day"},"jewels":[{"name":"Barrio Histórico + Calle de los Suspiros (12-block UNESCO quarter)","si_tag":"culture_heritage","tier":"essential","source":"https://www.adventurouskate.com/things-to-do-in-colonia-del-sacramento-uruguay/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"guided walk DMC 10–20% / affiliate 4–8%; museum ticket non-commissionable"},{"name":"The Lighthouse (Faro, 111 steps) + Portón de Campo city gate","si_tag":"culture_heritage","tier":"essential","source":"https://cuppatocopatravels.com/south-america/uruguay/colonia-del-sacramento-guide-uruguay/","timing":"summer Dec–Feb  + spring/fall shoulders","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"summer Dec–Feb  + spring/fall shoulders","commission":"guided-walk anchor DMC 10–20% / affiliate 4–8%; lighthouse entry non-commissionable"},{"name":"Plaza de Toros Real de San Carlos (restored 1910 bullring, reopened 2022)","si_tag":"culture_heritage","tier":"comfort","source":"https://www.tripadvisor.com/Attractions-g298066-Activities-Colonia_del_Sacramento_Colonia_Department.html","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"DMC add-on / guided circuit 10–20%"},{"name":"Vintage-car photo circuit","si_tag":"culture_heritage+romance","tier":"comfort","source":"https://www.guruguay.com/colonia-del-sacramento/","timing":"summer Dec–Feb  + spring/fall shoulders","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Colonia''s antique cars sit like sculpture on old-town corners; a curated photo/heritage-drive circuit is a natural romance+heritage crossover experience","si":"culture_heritage+romance","blurb":"Colonia''s antique cars sit like sculpture on old-town corners; a curated photo/heritage-drive circuit is a natural romance+heritage crossover experience","when":"summer Dec–Feb  + spring/fall shoulders","commission":"DMC / private-guide add-on 10–20%"},{"name":"Sunset on the Rambla Costanera","si_tag":"romance","tier":"essential","source":"https://cuppatocopatravels.com/south-america/uruguay/colonia-del-sacramento-guide-uruguay/","timing":"summer Dec–Feb  + spring/fall shoulders","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Colonia''s boardwalk fronts sandy beaches and small colonial homes rather than high-rises","si":"romance","blurb":"Colonia''s boardwalk fronts sandy beaches and small colonial homes rather than high-rises","when":"summer Dec–Feb  + spring/fall shoulders","commission":"content anchor — drives boutique-hotel + dining revenue"},{"name":"The overnight after the ferry leaves (converted-casona boutique)","si_tag":"romance","tier":"premier","source":"https://cuppatocopatravels.com/south-america/uruguay/colonia-del-sacramento-guide-uruguay/","timing":"summer Dec–Feb  + spring/fall shoulders","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"summer Dec–Feb  + spring/fall shoulders","commission":"boutique bedbank 10–18% / consortia"},{"name":"Buenos Aires day-ferry framing (romantic day-escape / overnight)","si_tag":"romance","tier":"comfort","source":"https://www.getyourguide.com/buenos-aires-l1/buenos-aires-to-colonia-tours-t314607/","timing":"summer Dec–Feb  + spring/fall shoulders","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"summer Dec–Feb  + spring/fall shoulders","commission":"ferry package / affiliate 4–10%"},{"name":"Carmelo Tannat wine day — Narbona + Bodega Cordano","si_tag":"culinary","tier":"premier","source":"https://matadornetwork.com/read/uruguay-wine-country/","timing":"summer Dec–Feb  + spring/fall shoulders","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the ~80 km up-river wine sub-region built on Tannat, Uruguay''s national grape. Narbona","si":"culinary","blurb":"the ~80 km up-river wine sub-region built on Tannat, Uruguay''s national grape. Narbona","when":"summer Dec–Feb  + spring/fall shoulders","commission":"DMC/guided wine day w/ transport 10–20% / affiliate 4–8%"}],"faq":[{"q":"What is there to do in Colonia del Sacramento''s Barrio Histórico?","a":"You can cover Colonia''s UNESCO Barrio Histórico on foot in about 4–5 hours including lunch: walk the ~12-block grid, the 1700s-era Calle de los Suspiros, the Plaza Mayor house-museums, and the Portón de Campo drawbridge gate, then climb the 111-step lighthouse for river-and-town views. It is compact because the Portuguese laid it out in 1680.","source":"guruguay.com, 2026-07-07","si_tag":"culture"},{"q":"Is Colonia worth an overnight, or just a day trip?","a":"Worth the overnight — that is the town''s quiet secret. Most travelers arrive on the day-ferry from Buenos Aires, so staying a night gives you the emptied cobbles at dusk and dawn and a sunset on the Rambla as the Río de la Plata turns copper. Book ahead: the top boutique, Charco, has only 8 rooms.","source":"cuppatocopatravels.com, 2026-07-07","si_tag":"romance"},{"q":"Can you do a wine day from Colonia del Sacramento?","a":"Yes — the wine day runs ~80 km up-river to Carmelo, Uruguay''s Tannat sub-region, with estate lunches at Narbona (a 1909-founded estate) and Bodega Cordano. Book it guided or with a driver: the fire to plan around is drink-and-drive on rural roads.","source":"matadornetwork.com, 2026-07-07","si_tag":"culinary"},{"q":"What''s the real risk to plan for in Colonia?","a":"Footing, not crime. The single most common visitor injury is a twist or fall on the Barrio Histórico''s uneven 300-year-old cobbles, which turn slick in the wet. Wear closed, gripped footwear and take extra care in rain and after dark — unguided walking is otherwise fine. Tap water is potable, and 911 is the nationwide emergency line.","source":"guruguay.com, 2026-07-07","si_tag":"safety"},{"q":"Do I need my passport for the Buenos Aires day-ferry?","a":"Yes — the crossing is an Argentina→Uruguay international border, and it is the single most common trip-planning error. Passengers clear immigration and customs at the terminal before boarding and check-in closes early, so arrive 1.5–2 hours before departure with your passport for both legs.","source":"directferries.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Colonia del Sacramento, Uruguay — UNESCO Barrio Histórico, the Lighthouse & a Carmelo Wine Day | TravelWell","search_language":"es-UY","local_keywords":["Colonia del Sacramento qué hacer","Barrio Histórico Colonia","Carmelo bodegas","ferry Buenos Aires Colonia","Calle de los Suspiros","Faro de Colonia del Sacramento","Tannat Uruguay","Rambla Colonia atardecer"],"hreflang":["en","es-UY"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07"},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Narbona Wine Lodge","brand":"Relais & Châteaux","area":"Carmelo (~80 km / ~1 hr from Colonia)","product":"5-room ultra-boutique estate, king rooms + private terraces, pool, winery, restaurant, Puerto Camacho boat access","earning":"Virtuoso/Fora consortia commission + amenities; MoR via consortium/DMC","tier":"ultra"},{"name":"Carmelo Resort & Spa","brand":"Hyatt Unbound Collection","area":"Carmelo (~1 hr from Colonia)","product":"44 keys incl. 24 bi-level suites + 20 detached villas, spa, tennis, indoor pool","earning":"Hyatt Privé / consortia commission + amenities; MoR via consortium/DMC","tier":"ultra"},{"name":"Charco Hotel","area":"Barrio Histórico, Colonia (riverfront, ~10-min walk from ferry port)","product":"8-room design boutique in converted original 1680 Portuguese houses, on-site restaurant + patio","earning":"consortia (Fora/Virtuoso where listed) + bedbank premium; MoR via consortium/bedbank","tier":"premier"}],"source_verified":null,"hero":{"query":"Colonia del Sacramento, Uruguay, Uruguay"},"geo":{"lat":-34.4718,"lng":-57.8446}}'::jsonb, 49),
  ('costalegre-mexico', '10S', 'Costalegre (Costa Alegre)', 'Mexico', 'Costalegre Mexico', 'live', 'verified', 'tropicalBeach', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"tropical","romance","ultra","ocean"}', '{"tropical"}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["~200 mi undeveloped Pacific coast between Puerto Vallarta and Manzanillo; PV->Barra de Navidad ~4-hr drive on Hwy 200","Five littoral areas: Bahia de Chamela, Costa Careyes, Cuixmala, Bahia de Tenacatita, Bahia de Navidad","Chamela-Cuixmala Biosphere Reserve ~32,000 acres tropical dry forest; UNAM research station since 1971","Humpback whales migrate Dec-Mar; Chamela islands (Isla Cocinas/Pajarera) reachable by boat","Ultra enclaves Careyes, Cuixmala, Las Alamandas with private airstrips; Chalacatepec airport completed Mar 2024 (operational status pending)"],"safety":{"emergency":"911","hospital":"remote coast; serious cases route to Manzanillo (~1.5 hr from Careyes area) or Puerto Vallarta (~2-4 hr north); carry travel-medical + air-evac insurance","advisory_level":"L3","book_enabled":false,"tourist_zone_carveout":"none (southern Jalisco coast NOT a named carve-out)","air_access_verified":"Manzanillo (ZLO, Colima) / PVR - not into a named carve-out; new Chalacatepec airport planned (verify); private airstrips at Careyes/Cuixmala/Las Alamandas - founder-review flag","founder_flag":"private-airstrip ''resort-airstrip private-access'' clean-pass class - flag for founder review; content-only until founder rules on carve-out","malaria":"low - mosquito avoidance (not prophylaxis) for Jalisco coastal lowlands below 1,000 m","dengue":"circulates (Jalisco cases 2025; peak May-Nov) - daytime repellent","water":"drink bottled/purified","hurricane":"May-Nov - trip insurance for summer/fall","remote":"limited services between towns; carry water/fuel/meds; do NOT drive secondary roads after dark (advisory warning)","road_transfer":"transfers pass through non-carve-out southern Jalisco - the hold reason; daylight main-highway DMC transfers only if ever activated","dive":"nearest hyperbaric chambers in Puerto Vallarta and Manzanillo (1.5-4 hr away) - conservative profiles, DAN insurance, strict no-fly interval","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FC